import re
from pathlib import Path
from datetime import date

import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

TIERS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE',
     'NETT TOTAL', 'NET TOTAL'],
]

EXCLUSIONS = [
    'SUBTOTAL', 'SUB TOTAL',
    'TAX', 'GST', 'SST',
    'DISCOUNT', 'CHANGE', 'CASH TENDERED',
]

AMOUNT_RE = re.compile(r'(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.\d])')


def to_float(tok: str) -> float:
    return float(tok.replace(',', ''))


def fmt_amount(v: float) -> str:
    return f'{v:.2f}'


def normalize_numeric_tokens(line: str) -> str:
    def fix_token(tok: str) -> str:
        if not re.search(r'\d', tok):
            return tok
        t = tok
        t = t.replace('O', '0').replace('o', '0').replace('Q', '0')
        t = t.replace('l', '1').replace('I', '1').replace('|', '1')
        t = t.replace('S', '5').replace('B', '8')
        t = t.replace(':', '.') if re.search(r'\d:\d', tok) else t
        return t
    line = re.sub(r'\bRN\b', 'RM', line)
    line = re.sub(r'(\d{1,4})\s+(\d{2})\s*$', r'\1.\2', line)
    return ' '.join(fix_token(t) for t in line.split(' '))


def ocr_variants(image_path: Path):
    img = Image.open(image_path)
    gray = ImageOps.autocontrast(ImageOps.grayscale(img))
    w, h = gray.size
    up2 = gray.resize((w * 2, h * 2), Image.LANCZOS)
    specs = [
        (img, '--psm 6'),
        (gray, '--psm 6'),
        (up2, '--psm 6'),
        (gray, '--psm 4'),
    ]
    texts = []
    for im, cfg in specs:
        try:
            texts.append(pytesseract.image_to_string(im, config=cfg))
        except Exception:
            pass
    return texts


def is_excluded(upper_line: str) -> bool:
    return any(k in upper_line for k in EXCLUSIONS)


def extract_total(variant_texts):
    candidates = []  # (tier, value, line_idx, variant_idx)
    corroborators = set()
    for vi, raw in enumerate(variant_texts):
        lines = [normalize_numeric_tokens(l) for l in raw.splitlines()]
        for li, line in enumerate(lines):
            U = line.upper()
            if any(k in U for k in ('CASH', 'PAYMENT', 'ROUNDED', 'TENDERED', 'CHANGE', 'SUBTOTAL')):
                for m in AMOUNT_RE.finditer(line):
                    corroborators.add(to_float(m.group(1)))
            if is_excluded(U):
                continue
            for ti, kws in enumerate(TIERS):
                if any(k in U for k in kws):
                    amounts = [to_float(m.group(1)) for m in AMOUNT_RE.finditer(line)]
                    if amounts:
                        candidates.append((ti, amounts[-1], li, vi))
                    elif not re.search(r'\d', line):
                        # look ahead up to 2 non-excluded lines
                        for look in range(li + 1, min(li + 3, len(lines))):
                            nxt = lines[look]
                            if not nxt.strip():
                                continue
                            NU = nxt.upper()
                            if is_excluded(NU):
                                continue
                            nx = [to_float(m.group(1)) for m in AMOUNT_RE.finditer(nxt)]
                            if nx:
                                candidates.append((ti, nx[-1], look, vi))
                                break
                    break
    if not candidates:
        return None
    best_tier = min(c[0] for c in candidates)
    pool = [c for c in candidates if c[0] == best_tier]
    from collections import Counter
    freq = Counter(round(c[1], 2) for c in pool)
    corr_set = {round(x, 2) for x in corroborators}

    def score(c):
        v = round(c[1], 2)
        return (freq[v], 1 if v in corr_set else 0, c[2])

    pool.sort(key=score, reverse=True)
    return fmt_amount(pool[0][1])


DATE_PATTERNS = [
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})'), 'dmy4'),
    (re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'), 'ymd'),
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})\b'), 'dmy2'),
    (re.compile(r'(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})', re.I), 'dmony'),
]
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def _valid(y, mo, d):
    try:
        date(y, mo, d)
        return 2000 <= y <= 2099
    except Exception:
        return False


def extract_date(text):
    lines = text.splitlines()
    scored = []
    for i, ln in enumerate(lines):
        boost = 1 if re.search(r'date|tarikh|inv', ln, re.I) else 0
        scored.append((boost, i, ln))
    scored.sort(key=lambda x: (-x[0], x[1]))
    for _, _, ln in scored:
        for rx, kind in DATE_PATTERNS:
            m = rx.search(ln)
            if not m:
                continue
            if kind == 'dmy4':
                d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                if mo > 12 and d <= 12:
                    d, mo = mo, d
            elif kind == 'ymd':
                y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            elif kind == 'dmy2':
                d, mo, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                y = 2000 + yy if yy <= 49 else 1900 + yy
            elif kind == 'dmony':
                d = int(m.group(1))
                mo = MONTHS[m.group(2).lower()[:3]]
                y = int(m.group(3))
            if _valid(y, mo, d):
                return f'{y:04d}-{mo:02d}-{d:02d}'
    return None


def extract_receipt(image_path: Path):
    variants = ocr_variants(image_path)
    total = extract_total(variants)
    date_iso = None
    for raw in variants:
        date_iso = extract_date(raw)
        if date_iso:
            break
    return date_iso, total


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])

    files = sorted(p.name for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'})
    for name in files:
        d, t = extract_receipt(IMG_DIR / name)
        print(f'{name}: date={d}, total={t}')
        row = [name, d if d else None, t if t else None]
        ws.append(row)
        # Force total_amount as text to preserve two-decimal formatting
        cell = ws.cell(row=ws.max_row, column=3)
        if cell.value is not None:
            cell.number_format = '@'

    wb.save(OUT_XLSX)


if __name__ == '__main__':
    main()
